// The MCP App page of skkg_view_image. src/apps/image-viewer.html is generated by `npm run build:viewer`.

import { readFileSync } from 'node:fs';
import { registerAppResource, RESOURCE_MIME_TYPE } from '@modelcontextprotocol/ext-apps/server';
import { VIEWER_RESOURCE_URI } from '../tools/view_image.js';
import { IIIF_IMAGE_BASE } from '../config.js';

const html = readFileSync(new URL('./image-viewer.html', import.meta.url), 'utf8');

// SKKG's IIIF server only: OpenSeadragon reads info.json with XHR (connect) and draws the tiles (resource).
const IIIF_ORIGIN = new URL(IIIF_IMAGE_BASE).origin;
const UI_META = { csp: { resourceDomains: [IIIF_ORIGIN], connectDomains: [IIIF_ORIGIN] }, prefersBorder: false };

export function registerViewerResource(server) {
  registerAppResource(server, 'SKKG image viewer', VIEWER_RESOURCE_URI,
    { description: 'Zoomable viewer of SKKG\'s published images, with their rights.', mimeType: RESOURCE_MIME_TYPE, _meta: { ui: UI_META } },
    async () => ({ contents: [{ uri: VIEWER_RESOURCE_URI, mimeType: RESOURCE_MIME_TYPE, text: html, _meta: { ui: UI_META } }] }));
}
